"""CLI-contract tests for src/scripts/gate.py -- the plugin's deterministic
gate dispatcher. Design spec: docs/audits/2026-09-04-determinism-audit.md,
sections 3.1, 3.2, 5.

This file owns: the exit-code contract (ACI-03: 0=pass, 1=fail,
2=could not run) across subcommands, the --json output shape, the
human-readable fallback output, and the ledger (session-state.json) merge
side effect described in the module docstring of gate.py. Per-gate logic
(argument-graph, coverage, citation-floor, changes-schema) is covered in
their own test_gate_*.py files.

Invocation pattern matches tests/test_proofread_scripts.py: scripts are run
as real subprocesses and asserted on returncode + stdout, so these tests
exercise the actual CLI a caller (or the gate-enforce Stop hook) would
invoke -- not gate.py's Python internals directly.
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")
FIXTURES = os.path.join(ROOT_DIR, "tests", "fixtures", "gate")


def run_gate(*args, env=None, inject_ledger=True):
    """Invoke gate.py as a real subprocess. By default, auto-injects a
    scratch --ledger into a throwaway tempdir when the caller didn't
    supply one -- without this, gate.py resolves the ledger via
    $CLAUDE_PROJECT_DIR (or cwd) and would write into any REAL
    .academic-helper/session-state.json that happens to exist there
    (TST-09 spirit: no ambient-environment dependency, including this
    one). Pass inject_ledger=False for the one test that deliberately
    exercises the $CLAUDE_PROJECT_DIR resolution fallback itself.
    """
    if inject_ledger and "--ledger" not in args and args:
        with tempfile.TemporaryDirectory() as ledger_dir:
            return subprocess.run(
                [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
                capture_output=True,
                text=True,
                timeout=30,
                env=env,
            )
    return subprocess.run(
        [sys.executable, GATE, *args],
        capture_output=True,
        text=True,
        timeout=30,
        env=env,
    )


class TestExitCodeContract(unittest.TestCase):
    def test_pass_exits_zero(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            proc = run_gate(
                "argument-graph",
                os.path.join(FIXTURES, "outline-valid.json"),
                "--ledger",
                os.path.join(tmpdir, "session-state.json"),
                "--json",
            )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")

    def test_missing_subcommand_exits_two(self):
        proc = run_gate()
        self.assertEqual(proc.returncode, 2)

    def test_unreadable_input_file_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            proc = run_gate(
                "argument-graph",
                os.path.join(tmpdir, "does-not-exist.json"),
                "--json",
            )
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "error")

    def test_malformed_json_exits_two_not_one(self):
        """Proves exit 1 (gate failed) and exit 2 (could not run) are
        genuinely distinguishable -- a caller must never confuse 'your
        outline has a cycle' with 'I couldn't parse your outline'.
        """
        with tempfile.TemporaryDirectory() as tmpdir:
            bad_path = os.path.join(tmpdir, "bad.json")
            with open(bad_path, "w", encoding="utf-8") as fh:
                fh.write("{ this is not valid JSON")
            proc = run_gate("argument-graph", bad_path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "error")
        self.assertNotEqual(payload["status"], "fail")

    def test_fail_exits_one_and_is_distinct_from_error(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            outline = {
                "sections": [
                    {"id": "A", "claim": "x", "evidence": [], "depends_on": [], "thesis_link": "t"}
                ]
            }
            path = os.path.join(tmpdir, "outline.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(outline, fh)
            proc = run_gate("argument-graph", path, "--json")
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "fail")


class TestJsonOutputShape(unittest.TestCase):
    def test_json_object_has_required_keys(self):
        proc = run_gate(
            "changes-schema",
            os.path.join(FIXTURES, "changes-valid.json"),
            "--json",
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        payload = json.loads(proc.stdout)
        for key in ("gate", "status", "detail", "violations"):
            self.assertIn(key, payload)
        self.assertEqual(payload["gate"], "changes-schema")
        self.assertIn(payload["status"], ("pass", "fail", "error"))
        self.assertIsInstance(payload["violations"], list)

    def test_json_mode_prints_exactly_one_line_on_pass(self):
        proc = run_gate(
            "changes-schema",
            os.path.join(FIXTURES, "changes-valid.json"),
            "--json",
        )
        lines = [ln for ln in proc.stdout.splitlines() if ln.strip()]
        self.assertEqual(len(lines), 1)


class TestHumanReadableOutput(unittest.TestCase):
    def test_non_json_pass_is_short(self):
        proc = run_gate("changes-schema", os.path.join(FIXTURES, "changes-valid.json"))
        self.assertEqual(proc.returncode, 0, proc.stderr)
        lines = [ln for ln in proc.stdout.splitlines() if ln.strip()]
        self.assertEqual(len(lines), 1, proc.stdout)
        self.assertIn("PASS", proc.stdout)

    def test_non_json_fail_lists_violations(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            payload = {"stage": "mechanical", "changes": [{"stage": "mechanical"}]}
            path = os.path.join(tmpdir, "changes.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(payload, fh)
            proc = run_gate("changes-schema", path)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        self.assertIn("FAIL", proc.stdout)
        self.assertIn("check=schema", proc.stdout)


class TestLedgerMerge(unittest.TestCase):
    def test_ledger_merge_preserves_pre_existing_keys(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            helper_dir = os.path.join(tmpdir, ".academic-helper")
            os.makedirs(helper_dir)
            ledger_path = os.path.join(helper_dir, "session-state.json")
            with open(ledger_path, "w", encoding="utf-8") as fh:
                json.dump({"run": {"id": "run-1", "skill": "write"}, "other": "keep-me"}, fh)

            proc = run_gate(
                "argument-graph",
                os.path.join(FIXTURES, "outline-valid.json"),
                "--ledger",
                ledger_path,
                "--json",
            )
            self.assertEqual(proc.returncode, 0, proc.stderr)

            with open(ledger_path, encoding="utf-8") as fh:
                merged = json.load(fh)

        self.assertEqual(merged["run"], {"id": "run-1", "skill": "write"})
        self.assertEqual(merged["other"], "keep-me")
        self.assertIn("gates", merged)
        self.assertIn("argument-graph", merged["gates"])
        entry = merged["gates"]["argument-graph"]
        self.assertEqual(entry["status"], "pass")
        self.assertIn("at", entry)
        self.assertIn("detail", entry)
        self.assertEqual(entry["violations"], [])

    def test_ledger_merge_records_failure_status(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            helper_dir = os.path.join(tmpdir, ".academic-helper")
            os.makedirs(helper_dir)
            ledger_path = os.path.join(helper_dir, "session-state.json")

            bad_outline = {
                "sections": [
                    {"id": "A", "claim": "x", "evidence": [], "depends_on": [], "thesis_link": "t"}
                ]
            }
            outline_path = os.path.join(tmpdir, "outline.json")
            with open(outline_path, "w", encoding="utf-8") as fh:
                json.dump(bad_outline, fh)

            proc = run_gate(
                "argument-graph", outline_path, "--ledger", ledger_path, "--json"
            )
            self.assertEqual(proc.returncode, 1, proc.stderr)

            with open(ledger_path, encoding="utf-8") as fh:
                merged = json.load(fh)

        entry = merged["gates"]["argument-graph"]
        self.assertEqual(entry["status"], "fail")
        self.assertTrue(len(entry["violations"]) >= 1)

    def test_ledger_write_skipped_silently_when_academic_helper_absent(self):
        """Never create .academic-helper/ outside the setup/init skills
        (CLAUDE.md anti-pattern rule) -- if the resolved ledger path's
        parent directory doesn't already exist, the write must be skipped
        silently and the gate's real exit code must still come through.
        """
        with tempfile.TemporaryDirectory() as tmpdir:
            ledger_path = os.path.join(tmpdir, ".academic-helper", "session-state.json")
            self.assertFalse(os.path.isdir(os.path.dirname(ledger_path)))

            proc = run_gate(
                "argument-graph",
                os.path.join(FIXTURES, "outline-valid.json"),
                "--ledger",
                ledger_path,
                "--json",
            )

        self.assertEqual(proc.returncode, 0, proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")
        # The directory must still not exist -- gate.py must never create it.
        self.assertFalse(os.path.isdir(os.path.dirname(ledger_path)))

    def test_ledger_path_resolves_from_claude_project_dir_env(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            helper_dir = os.path.join(tmpdir, ".academic-helper")
            os.makedirs(helper_dir)
            env = dict(os.environ)
            env["CLAUDE_PROJECT_DIR"] = tmpdir

            proc = run_gate(
                "argument-graph",
                os.path.join(FIXTURES, "outline-valid.json"),
                "--json",
                env=env,
                inject_ledger=False,
            )
            self.assertEqual(proc.returncode, 0, proc.stderr)

            ledger_path = os.path.join(helper_dir, "session-state.json")
            self.assertTrue(os.path.isfile(ledger_path))
            with open(ledger_path, encoding="utf-8") as fh:
                merged = json.load(fh)
        self.assertIn("argument-graph", merged["gates"])


if __name__ == "__main__":
    unittest.main()
